import re
src = '''import re

_UNIT_SCALE = {"h": 3600, "m": 60, "s": 1}
_UNIT_RANK = {"h": 0, "m": 1, "s": 2}
_DURATION_RE = re.compile(r"(\\d+)([hms])")


def slugify(text):
    """Lowercase; runs outside [a-z0-9] collapse to a single "-"; strip edges."""
    return re.sub(r"[^a-z0-9]+", "-", str(text).lower()).strip("-")


def truncate(text, limit, suffix="..."):
    """Cut *text* to *limit* characters, appending *suffix* when truncating."""
    text = str(text)
    limit = int(limit)
    if len(text) <= limit:
        return text
    if limit < len(suffix):
        return suffix[:limit]
    return text[:limit - len(suffix)] + suffix


def parse_duration(text):
    """Parse strings like "45s", "2m", "1h30m", "2h15m10s" into seconds."""
    if not isinstance(text, str):
        raise ValueError("bad duration: %r" % (text,))
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("bad duration: %r" % (text,))

    total = 0
    pos = 0
    previous_rank = -1
    seen = set()
    while pos < len(cleaned):
        match = _DURATION_RE.match(cleaned, pos)
        if not match:
            raise ValueError("bad duration: %r" % (text,))
        amount, unit = match.group(1), match.group(2)
        rank = _UNIT_RANK[unit]
        if unit in seen or rank <= previous_rank:
            raise ValueError("bad duration: %r" % (text,))
        seen.add(unit)
        previous_rank = rank
        total += int(amount) * _UNIT_SCALE[unit]
        pos = match.end()

    return total


def chunk(items, size):
    """Split *items* into a list of lists of length *size* (last may be shorter)."""
    if size <= 0:
        raise ValueError("chunk size must be positive, got %r" % (size,))
    items = list(items)
    return [items[start:start + size] for start in range(0, len(items), size)]


def word_count(text):
    """Count whitespace-separated tokens containing at least one alphanumeric."""
    return sum(
        1
        for token in str(text).split()
        if any(char.isalnum() for char in token)
    )
